export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"ja","term":"時価総額（マーケットキャップ）","aka":["時価総額","マーケットキャップ","Market cap"],"short":"時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。","body":[["計算式は「価格 × ",["流通供給量","circulating-supply"],"」です。1枚の価格だけでは銘柄の大きさは比べられません。1枚10円のコインでも発行枚数が膨大なら、1枚100万円のコインより時価総額が大きいことがあります。"],["時価総額は、銘柄の規模感や値動きの傾向をつかむのに役立ちます。一般に、時価総額が大きい銘柄ほど",["流動性","liquidity"],"が高く値動きが比較的穏やかで、小さい銘柄ほど少ない資金で価格が大きく動きやすい傾向があります。"],["ただし、時価総額は「全量をその価格で売れる」ことを意味しません。流通量が少なく板の薄い銘柄では、表示上の時価総額が実態より大きく見えることがあります。また、データサイトによって流通供給量の数え方が違うため、時価総額の数字が一致しないこともあります。将来の供給増を考えるには、",["完全希薄化後時価総額（FDV）","fully-diluted-valuation"],"もあわせて確認しましょう。"]],"example":"例えば、コインAは価格2円・流通量500億枚、コインBは価格5,000円・流通量1,000万枚だとします。時価総額はAが2 × 500億 = 1,000億円、Bが5,000 × 1,000万 = 500億円です。1枚の価格はBのほうが2,500倍高いのに、市場規模はAがBの2倍あります。","mistakes":["1枚の価格が安いことを理由に「まだ割安だ」と判断すること。","時価総額の金額を、そのまま売却できる金額だと考えること。","流通量が少なくロック中のトークンが多い銘柄で、FDVを確認しないこと。"],"faq":[{"q":"時価総額が大きい銘柄は安全ですか？","a":"一般に流動性が高く値動きは比較的穏やかですが、価格が下がらないという意味ではありません。大型銘柄でも大きく下落することはあります。"},{"q":"時価総額ランキングはどこで見られますか？","a":"CoinGeckoやCoinMarketCapなどのデータサイトや、多くの取引所アプリで確認できます。サイトによって数値が少し異なることがあります。"}],"title":"時価総額（マーケットキャップ）とは？計算方法と見方","description":"暗号資産の時価総額の意味と計算方法、1枚の価格だけで銘柄の大きさを判断してはいけない理由を具体例で解説します。","related":[["fully-diluted-valuation","完全希薄化後時価総額（FDV）","完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。"],["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。"],["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"],["altcoin","アルトコイン","アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"ja","term":"マーケットメイカー（MM）","aka":["マーケットメーカー","MM","market maker"],"short":"マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。","body":[["マーケットメイカーは、現在値の少し下に買い注文、少し上に売り注文を常に並べます。誰かが成行で買えば売り注文が、売れば買い注文が約定し、その差である",["スプレッド","bid-ask-spread"],"を少しずつ収益にします。在庫が偏ると価格がどちらかに動いたときに損をするため、注文価格を調整したり、先物で",["ヘッジ","hedging"],"したりしてリスクを管理します。"],[["暗号資産","cryptocurrency"],"取引所では、専門のマーケットメイカー企業が取引所やトークン発行体と契約して",["流動性","liquidity"],"を提供していることが多く、",["メイカー手数料","maker-taker-fees"],"の割引やリベートを受けている場合もあります。",["新規上場","token-listing"],"トークンの板が最初から厚いのは、こうした契約によることが少なくありません。"],"分散型取引所では、人が板に注文を出す代わりに、AMM（自動マーケットメイカー）と呼ばれる仕組みと流動性プールが同じ役割を担います。マーケットメイカーがいなくなると板が薄くなり、スプレッドが広がるため、個人トレーダーの取引コストにも直結します。"],"example":"あるマーケットメイカーが、ETHに対して2,998 USDTで買い、3,002 USDTで売る注文を出しているとします。スプレッドは4 USDTです。同じ時間帯に1 ETHずつ買いと売りが約定すれば、手数料を除いて4 USDTの利益になります。これを1日500回繰り返すと2,000 USDTです。しかし買いだけが約定して在庫を10 ETH抱えた直後に価格が2,950 USDTまで下がれば、約480 USDTの評価損が出ます。","mistakes":["マーケットメイカーは常に価格を一方向に操作している存在だと決めつける。","急変時にもマーケットメイカーが板を支えてくれると考え、注文が一斉に引かれてスプレッドが広がる可能性を想定しない。","取引所の「メイカー」とマーケットメイカー企業を同じものだと混同する。"],"faq":[{"q":"マーケットメイカーはどうやって利益を出していますか？","a":"主に買い値と売り値の差であるスプレッドと、取引所からのリベートで利益を得ます。在庫の価格変動で損をすることもあるため、ヘッジでリスクを抑えます。"},{"q":"個人でもマーケットメイカーになれますか？","a":"指値注文を板に出せば個人もメイカーとして流動性を提供できます。ただし専業のマーケットメイカーは高速なシステムと大きな資金で運用しており、同じ条件ではありません。"}],"title":"マーケットメイカーとは？役割と仕組み","description":"マーケットメイカー（MM）の意味、スプレッドで利益を出す仕組み、在庫リスク、AMMとの違いを具体的な数字でわかりやすく解説します。","related":[["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"ja","term":"リスクリワードレシオ（損益比率）","aka":["リスクリワード","RRR","損益比率","リスクリワード比"],"short":"リスクリワードレシオとは、1回の取引で想定する損失額（リスク）と利益額（リワード）の比率のことで、例えば損失100に対して利益200なら1対2と表します。","body":[["エントリー前に、",["損切り","stop-loss"],"価格と利益確定価格を決めると、リスクとリワードの値幅がわかります。買いの場合、リスクはエントリー価格から損切り価格まで、リワードはエントリー価格から利確価格までです。これを比で表したのがリスクリワードレシオで、取引を始める前に「割に合うか」を判断する材料になります。"],"リスクリワードは勝率とセットで考える必要があります。1対2の取引なら、勝率が約34%を超えれば手数料を除いて長期的にプラスになり得ます。反対に、1対0.5のような取引を続けるなら、勝率が約67%以上ないと合計で負けてしまいます。損益分岐の勝率は、リスク÷（リスク＋リワード）で求められます。",["ただし、利確目標を遠くに置けばリスクリワードは良く見えますが、そこまで届く確率は下がります。",["サポート","support-and-resistance"],"やレジスタンスなど現実的な目標に基づいて設定し、手数料も含めて計算するのが大切です。",["OCO注文","oco-order"],"を使えば、利確と損切りを同時に設定できます。"]],"example":["BTCを64,000 USDTで買い、損切りを62,400 ",["USDT","usdt"],"、利確を68,800 USDTに置くとします。リスクは1,600 USDT、リワードは4,800 USDTなので、リスクリワードレシオは1対3です。損益分岐の勝率は1,600÷（1,600＋4,800）＝25%です。10回取引して3回勝ち7回負ければ、4,800×3−1,600×7＝3,200 USDTのプラスになります（1 BTCあたり、手数料除く）。"],"mistakes":["勝率を考えずに、リスクリワードの数字だけを良く見せようとして非現実的な利確目標を置く。","エントリー後に損切りを遠くへずらし、事前に計算したリスクリワードを自分で崩してしまう。","手数料やスリッページを計算に入れず、実際の損益比率が想定より悪くなる。"],"faq":[{"q":"リスクリワードレシオはいくつが理想ですか？","a":"1対2以上を目安にする人が多いですが、理想は勝率とのバランスで決まります。勝率が高い手法なら1対1でも成り立ちます。"},{"q":"リスクリワードの計算方法は？","a":"エントリーから損切りまでの値幅をリスク、エントリーから利確までの値幅をリワードとし、リスク対リワードの比で表します。"}],"title":"リスクリワードレシオとは？計算方法と勝率の関係","description":"リスクリワードレシオの意味と計算方法、損益分岐となる勝率の求め方、利確と損切りの設定でよくある失敗を具体例で解説します。","related":[["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"],["oco-order","OCO注文","OCO注文とは、2つの注文を同時に出し、どちらか一方が約定するともう一方が自動的に取り消される注文方法です。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"いくら買うか決める前に、いくら失えるかを決めよ"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"ja","term":"先物取引（先物契約）","aka":["先物","先物契約","フューチャーズ","futures"],"short":"先物取引とは、ある資産を将来の特定の時点に、あらかじめ決めた価格で売買することを約束する契約で、暗号資産では現物を持たずに価格変動の差額だけをやり取りするのが一般的です。","body":[[["現物取引","spot-trading"],"では実際にBTCやETHを買って保有しますが、先物取引で売買するのは「価格に連動する契約」です。",["暗号資産","cryptocurrency"],"の先物の多くは差金決済で、決済時には価格差の分だけ証拠金が増減します。そのため、値上がりを狙う買い（",["ロング","long-and-short"],"）だけでなく、値下がりで利益が出る売り（ショート）も同じように簡単に持てます。"],["暗号資産の先物には大きく2種類あります。満期日が決まっていて、その日に決済される限月（デリバリー）先物と、満期がなく",["資金調達率","funding-rate"],"で価格を現物に近づける",["無期限先物（パーペチュアル）","perpetual-futures"],"です。",["取引量","trading-volume"],"では無期限先物が圧倒的に多く、海外の大手取引所ではUSDT建てとコイン建ての両方が提供されています。"],"先物では証拠金を差し入れてレバレッジをかけられるため、少ない資金で大きなポジションを持てる一方、損失も同じ比率で大きくなります。証拠金が足りなくなると強制ロスカットされます。日本国内の暗号資産交換業者では、個人向けの暗号資産デリバティブのレバレッジ上限は2倍です。"],"example":"BTCが60,000 USDTのとき、想定元本0.5 BTC（30,000 USDT）分の先物を買い、証拠金を3,000 USDT入れたとします（10倍）。BTCが63,000 USDTに上がって決済すれば、利益は（63,000−60,000）×0.5＝1,500 USDTで、証拠金に対して50%です。逆に57,000 USDTに下がれば1,500 USDTの損失となり、証拠金の半分を失います。","mistakes":["先物で買ったBTCを、現物と同じように自分のウォレットへ出金できると考える。","値動きの割合とレバレッジを掛けた損益の割合を混同し、損失の大きさを過小評価する。","無期限先物と限月先物の違いを知らず、満期日の自動決済や資金調達率の支払いに驚く。"],"faq":[{"q":"先物取引と現物取引の違いは何ですか？","a":"現物取引は資産そのものを売買して保有し、先物取引は価格に連動する契約を売買します。先物はレバレッジやショートが使える一方、強制ロスカットのリスクがあります。"},{"q":"暗号資産の先物は日本でも取引できますか？","a":"国内の登録業者でも暗号資産のデリバティブ取引が提供されており、個人のレバレッジ上限は2倍です。海外取引所の利用については、各国の規制や取引所の対応地域を確認してください。"}],"title":"暗号資産の先物取引とは？仕組みと現物との違い","description":"暗号資産の先物取引の仕組み、現物取引との違い、無期限先物と限月先物、レバレッジと強制ロスカットの関係を具体例で解説します。","related":[["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["delivery-futures","限月先物（デリバリー先物・四半期先物）","限月先物とは、満期日（決済日）があらかじめ決まっている先物契約で、満期になると自動的に決済され、暗号資産では四半期ごとの契約がよく使われます。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"ja","term":"クロスマージン","aka":["クロス","全額証拠金","cross margin","クロスモード"],"short":"クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。","body":[["クロスマージンでは、ポジションごとに証拠金を区切らず、先物口座の残高全体がすべてのポジションの担保になります。あるポジションに",["含み損","unrealized-pnl"],"が出ても、口座の残高や他のポジションの含み益で穴埋めされるため、",["分離マージン","isolated-margin"],"より清算されにくくなります。"],["ただしこれは、損失が大きくなったときに口座全体が巻き込まれることを意味します。1つのポジションが大きく逆行すると、他の健全なポジションの証拠金まで削られ、最悪の場合は口座の残高のほぼすべてが清算で失われます。清算の判定は個別のポジションではなく、口座全体の証拠金と",["維持証拠金","maintenance-margin"],"の比率で行われます。"],[["ヘッジ","hedging"],"のために反対方向のポジションを持つ場合や、複数のポジションを組み合わせて運用する場合に便利です。取引所によっては統合証拠金口座のように、現物残高も含めて担保として使える仕組みもあります。どの資産が担保として何割で評価されるかは取引所ごとに確認してください。"]],"example":["先物口座に4,000 USDTがあり、クロスマージンでETHの",["ロング","long-and-short"],"（維持証拠金150 ",["USDT","usdt"],"）とBTCのロング（維持証拠金250 USDT）を持っているとします。ETHが急落して含み損が2,500 USDTになっても、BTCに含み益が300 USDTあれば口座の証拠金は4,000−2,500＋300＝1,800 USDTで、維持証拠金の合計400 USDTを上回るため清算されません。しかし損失がさらに膨らんで残高が400 USDTを割れば、両方のポジションが清算対象になります。"],"mistakes":["クロスマージンでは清算されないと思い込み、口座全体を失うリスクを見落とす。","先物口座に余剰資金をすべて入れたまま、クロスマージンで高レバレッジの取引をする。","あるポジションの含み益が、別のポジションの損失の穴埋めに使われていることに気づかない。"],"faq":[{"q":"クロスマージンのメリットは何ですか？","a":"口座全体の証拠金を共有するため、一時的な逆行で清算されにくく、ヘッジや複数ポジションの運用がしやすい点です。"},{"q":"クロスマージンで清算されるとどうなりますか？","a":"口座全体の証拠金が維持証拠金を下回ると清算が始まり、場合によっては口座の残高の大部分を失います。先物口座に置く金額を限定しておくことが大切です。"}],"title":"クロスマージンとは？分離マージンとの違いとリスク","description":"クロスマージンの仕組み、証拠金を共有するメリットと口座全体を失うリスク、分離マージンとの使い分けを具体例で解説します。","related":[["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["portfolio-margin","ポートフォリオマージン","ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。"],["unified-trading-account","統合取引口座（UTA）","統合取引口座（UTA）とは、現物、先物、オプションなどの取引を1つの口座でまとめて行い、口座内の資産全体を証拠金として共有できる取引所の口座形態です。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"クロスマージン：なぜ一つの損失が他のポジションに波及するのか"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"ja","term":"ロングとショート（買いポジション・売りポジション）","aka":["ロング","ショート","買いポジション","売りポジション"],"short":"ロングとショートとは、価格の上昇で利益が出る買いのポジション（ロング）と、価格の下落で利益が出る売りのポジション（ショート）のことです。","body":[["ロングは、安く買って高く売ることを狙う立場です。現物でBTCを買って持つのも、先物で買いポジションを建てるのもロングです。ショートは、先に売って後で安く買い戻すことを狙う立場で、価格が下がるほど利益が出ます。",["暗号資産","cryptocurrency"],"では主に先物や",["証拠金取引","margin-trading"],"を使ってショートします。"],["ロングの損失は、価格がゼロになれば投じた額までと限られますが、ショートの損失は理論上、価格が上がり続ける限り大きくなります。",["レバレッジ","leverage"],"をかけた場合は、どちらも",["清算価格","liquidation-price"],"に達すると証拠金を失います。"],["ロングとショートは投機だけでなく、",["ヘッジ","hedging"],"にも使われます。現物を持ったまま先物でショートすれば、値下がりの損失を先物の利益で相殺できます。取引所の画面では、ロングが「買い」や「ロング」、ショートが「売り」や「ショート」と表示され、決済には反対の注文を出します。"]],"example":["SOLが180 USDTのとき、先物で10 SOLのロングを建てたとします。200 USDTに上がって決済すれば利益は（200−180）×10＝200 USDTで、160 USDTに下がれば200 USDTの損失です。反対に180 USDTで10 SOLのショートを建てた場合、160 USDTで買い戻せば200 USDTの利益、200 USDTに上がれば200 USDTの損失になります。手数料と",["資金調達率","funding-rate"],"は別に計算します。"],"mistakes":["ショートの決済方法がわからず、決済のつもりで新たにロングを建ててしまう。","ショートの損失には上限がないことを忘れ、損切りを置かずに持ち続ける。","ロングとショートを同時に持てば必ず損をしないと考え、手数料と資金調達率のコストを見落とす。"],"faq":[{"q":"ショートは現物取引でもできますか？","a":"通常の現物取引ではできません。先物取引や、コインを借りて売る証拠金取引を使います。"},{"q":"ロングとショートを同時に持つことはできますか？","a":"取引所の両建てモードを使えば同じ銘柄で同時に持てます。ただし相殺されるため、手数料や資金調達率のコストだけがかかる場合があります。"}],"title":"ロングとショートとは？意味と損益の違い","description":"ロング（買い）とショート（売り）の意味、損益の計算方法、ショートの損失に上限がない理由やヘッジへの使い方を解説します。","related":[["short-selling","空売り（ショートセリング）","空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["long-short-ratio","ロングショート比率","ロングショート比率とは、先物市場でロング（買い）を持っている口座やポジションと、ショート（売り）を持っているものの割合を比べた指標で、市場参加者の偏りを見るのに使われます。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"ja","term":"空売り（ショートセリング）","aka":["ショート","空売り","売り建て","short selling"],"short":"空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。","body":[["空売りには、手元にない資産を売るための仕組みが必要です。",["暗号資産","cryptocurrency"],"では主に2つの方法があります。1つは先物や",["無期限先物","perpetual-futures"],"でショートポジションを建てる方法、もう1つは現物の",["証拠金取引","margin-trading"],"でコインを借りて売り、後で買い戻して返す方法です。個人が使うのは先物のほうが一般的です。"],["空売りの損失は、価格が上がり続ける限り大きくなります。",["上昇相場","bull-market"],"で売り方が",["損切り","stop-loss"],"や清算のために一斉に買い戻すと、さらに価格が跳ね上がる",["ショートスクイーズ","short-squeeze"],"が起きることもあります。コインを借りる方式では借入利息、先物では資金調達率がかかるため、長く持つほどコストが増えます。"],"空売りは下落相場で利益を狙うだけでなく、手持ちの現物の値下がりリスクを抑えるヘッジとしても使われます。国や取引所によって提供の有無や条件が異なるため、利用前に確認してください。"],"example":"ETHが3,500 USDTのとき、証拠金取引で3 ETHを借りて売り、10,500 USDTを受け取ったとします。ETHが3,150 USDTに下がったところで3 ETHを9,450 USDTで買い戻して返せば、差額は1,050 USDTの利益です。借入利息が1日0.01%で10日なら、3 ETHに対して約0.003 ETH（約10 USDT相当）がかかります。反対にETHが3,850 USDTに上がれば、買い戻しに11,550 USDTかかり、1,050 USDTの損失です。","mistakes":["空売りの損失は売った金額までだと誤解し、損切りを置かない。","下がり続けている銘柄なら空売りで簡単に利益が出ると考え、急反発による踏み上げを想定しない。","借入利息や資金調達率を計算に入れず、長期間ショートを持ち続ける。"],"faq":[{"q":"空売りとショートは同じ意味ですか？","a":"ほぼ同じ意味で使われます。厳密には空売りは借りて売る行為を指し、ショートは売りポジション全般を指すことが多いです。"},{"q":"暗号資産の空売りにはどんなコストがかかりますか？","a":"売買手数料に加え、コインを借りる場合は借入利息、先物を使う場合は資金調達率の支払いがかかります。"}],"title":"空売り（ショートセリング）とは？暗号資産での仕組み","description":"暗号資産の空売り（ショートセリング）の仕組み、先物と証拠金取引での方法の違い、損失に上限がない理由とコストを解説します。","related":[["long-and-short","ロングとショート（買いポジション・売りポジション）","ロングとショートとは、価格の上昇で利益が出る買いのポジション（ロング）と、価格の下落で利益が出る売りのポジション（ショート）のことです。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。"],["short-squeeze","ショートスクイーズ（踏み上げ）","ショートスクイーズ（踏み上げ）とは、価格の上昇によってショートを持つ人が損切りや強制ロスカットで一斉に買い戻し、その買いがさらに価格を押し上げる現象です。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"ja","term":"ベーシス（先物と現物の価格差）","aka":["ベーシス","先物プレミアム","basis","先物ベーシス"],"short":"ベーシスとは、先物価格と現物価格の差のことで、先物が現物より高い状態をプレミアム（コンタンゴ）、安い状態をディスカウント（バックワーデーション）と呼びます。","body":[["ベーシスは「先物価格−現物価格」で計算され、率で表すときは現物価格で割ります。",["限月先物","delivery-futures"],"では満期までの期間が長いほどベーシスが大きくなる傾向があるため、比較しやすいように年率に換算して見るのが一般的です。満期日には先物が現物に収束するため、ベーシスはゼロに近づきます。"],[["暗号資産","cryptocurrency"],"では、強気の局面で",["レバレッジ","leverage"],"をかけて買いたい人が多いと、先物が現物より高くなりやすくなります。ベーシスが大きく開くと、現物を買って先物を売る「",["キャッシュ・アンド・キャリー","funding-rate-arbitrage"],"」と呼ばれる",["裁定取引","arbitrage"],"で、満期までの差額を狙う人が増え、差は縮まっていきます。"],[["無期限先物","perpetual-futures"],"には満期がないため、ベーシスの代わりに資金調達率が先物と現物の差を調整します。どちらも市場の過熱感を見る指標として使われますが、それだけで価格の方向は決まりません。"]],"example":"ETHの現物価格が2,500 USDTで、60日後に満期を迎える限月先物が2,540 USDTだとします。ベーシスは40 USDT、率にすると40÷2,500＝1.6%です。年率に換算すると1.6%×365÷60で約9.7%になります。現物を1 ETH買って先物を1 ETH売れば、満期には価格が一致するため、手数料を除いて約40 USDTの差額を確定できます。","mistakes":["満期までの期間が違う先物のベーシスを、年率換算せずにそのまま比べる。","ベーシスの裁定取引は無リスクだと考え、取引所のリスクや証拠金の管理を見落とす。","ベーシスが大きいことを、価格がこれから上がるサインだと決めつける。"],"faq":[{"q":"ベーシスがマイナスになるのはどんなときですか？","a":"先物が現物より安い状態で、売りが多い局面や、急落時に先物の売りが先行したときなどに見られます。バックワーデーションと呼ばれます。"},{"q":"ベーシスと資金調達率の関係は？","a":"限月先物ではベーシスが、無期限先物では資金調達率が、先物と現物の価格差を反映します。どちらも市場の偏りを示す指標です。"}],"title":"ベーシスとは？先物と現物の価格差の意味と計算","description":"先物のベーシス（先物と現物の価格差）の意味、コンタンゴとバックワーデーション、年率換算の計算方法と裁定取引への使い方を解説します。","related":[["delivery-futures","限月先物（デリバリー先物・四半期先物）","限月先物とは、満期日（決済日）があらかじめ決まっている先物契約で、満期になると自動的に決済され、暗号資産では四半期ごとの契約がよく使われます。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。"],["funding-rate-arbitrage","資金調達率アービトラージ（FRアービトラージ）","資金調達率アービトラージとは、現物を買うと同時に同じ数量の無期限先物をショートし、価格変動の影響を打ち消しながら資金調達率の受け取りを狙う取引です。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"ja","term":"送金ネットワーク（チェーン選択）","aka":["入金ネットワーク","出金ネットワーク","チェーン選択","ネットワーク選択"],"short":"送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。","body":[["USDTやUSDCのように、同じ銘柄が複数の",["ブロックチェーン","blockchain"],"で発行されている場合があります。取引所の出金画面でERC20（",["イーサリアム","ethereum"],"）、TRC20（トロン）、BEP20（BNB Chain）、Solana、Arbitrumなどの選択肢が出るのはこのためです。"],["ネットワークによって手数料や着金までの時間が大きく異なります。一般にイーサリアム本体は手数料が高めで、トロンや",["レイヤー2","layer-2"],"は安めの傾向がありますが、混雑状況や取引所の設定で変わります。"],"受取側がそのネットワークに対応していないと、資産が反映されなかったり、復旧に手数料と時間がかかったり、最悪の場合は失われたりします。必ず受取側の入金画面で対応ネットワークを確認してから出金しましょう。"],"example":["取引所Aから取引所Bへ1,000 USDTを送るとします。Bの入金画面がTRC20とERC20に対応していて、Aの",["出金手数料","withdrawal-fee"],"がTRC20で1 ",["USDT","usdt"],"、ERC20で5 USDTだったとすると、TRC20を選べば999 USDT、ERC20なら995 USDTが届きます。ただし、BがTRC20に対応していないのにTRC20で送れば、1,000 USDTが反映されない恐れがあります。手数料の安さより、一致の確認が先です。"],"mistakes":["受取側の対応ネットワークを確認せず、手数料の安いネットワークを選ぶこと。","ERC20とBEP20のように、同じ0xアドレス形式のネットワークを混同すること。","入金アドレスを過去にコピーしたものから使い回し、ネットワークの変更に気付かないこと。"],"faq":[{"q":"ネットワークを間違えて送金したらどうなりますか？","a":"受取側が取引所の場合、サポートに申請すれば復旧できることもありますが、対応しない取引所もあり、手数料がかかる場合があります。対応していないチェーンへの送金は失われる可能性があります。"},{"q":"どのネットワークを選べばよいですか？","a":"送金側と受取側の両方が対応しているネットワークの中から、手数料と着金時間を比べて選びます。迷ったら少額でテスト送金しましょう。"}],"title":"送金ネットワークとは？チェーン選択の意味と注意点","description":"暗号資産の入出金で選ぶ送金ネットワーク（ERC20・TRC20など）の意味、手数料の違い、選択を間違えたときのリスクを解説します。","related":[["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["memo-tag","メモ／宛先タグ（Memo・Destination Tag）","メモ（宛先タグ）とは、XRPやXLMなど一部の暗号資産で、同じ入金アドレスを共有する利用者の中から受取人を特定するための追加の番号や文字列です。"],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["withdrawal-fee","出金手数料","出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。"],["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"ja","term":"メンプール（Mempool）","aka":["メモリプール","mempool"],"short":"メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。","body":[[["ウォレット","crypto-wallet"],"から送金すると、その取引はまずネットワーク上の",["ノード","node"],"に広がり、各ノードのメンプールに保存されます。マイナーや",["バリデーター","validator"],"はメンプールから取引を選んでブロックに入れ、取り込まれた時点で1回目の承認となります。"],["ブロックに入る取引の量には上限があるため、混雑時は手数料の高い取引から優先的に処理されます。",["ビットコイン","bitcoin"],"では手数料率（sat/vB）、",["イーサリアム","ethereum"],"では",["ガス代","gas-fee"],"の優先手数料が順番を左右します。手数料を低く設定しすぎると、取引が長時間メンプールに残ることがあります。"],"メンプールの取引は公開されているため、イーサリアムなどではそれを見て自分の取引を先に差し込む「フロントランニング」（MEVの一種）が起こることがあります。また、ノードごとにメンプールの中身は少しずつ異なり、ひとつの「全体共通の待合室」があるわけではありません。"],"example":"ビットコインのメンプールが混雑していて、次のブロックに入る目安が20 sat/vB、あなたの送金は5 sat/vBで出していたとします。取引サイズが140 vBなら手数料は700 satsで、20 sat/vBなら2,800 satsが必要です。このままでは数時間から数日待つ可能性があります。ウォレットがRBF（手数料の引き上げ）に対応していれば、25 sat/vB、つまり3,500 satsに上げた取引で置き換えることで、次の数ブロックのうちに承認される可能性が高まります。","mistakes":["未承認の送金がなかなか進まないので、同じ送金を別に作成して二重に送ってしまう。","混雑状況を確認せず、ウォレットの最低手数料で急ぎの送金を出してしまう。","メンプールに表示された時点で入金が完了したと考え、承認前に取引を進めてしまう。"],"faq":[{"q":"メンプールに残った取引はどうなりますか？","a":"手数料が上がるか混雑が解消されればブロックに取り込まれます。長期間取り込まれない取引は、ノードのメンプールから削除されることがあり、その場合は資金がウォレットに戻った状態になります。"},{"q":"メンプールの混雑状況はどこで確認できますか？","a":"ビットコインならmempool.spaceなどのサイトで、待機中の取引量や推奨手数料を確認できます。"}],"title":"メンプールとは？未承認取引と送金が遅い理由","description":"メンプールの意味、未承認の取引が待機する仕組み、手数料と処理順の関係、送金が遅いときの対処法を具体例で解説します。","related":[["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"],["mev","MEV（最大抽出可能価値）","MEV（最大抽出可能価値）とは、ブロックに入れる取引の順番を並べ替えたり、取引を差し込んだりすることで、ブロック生成者や専門のボットが得られる追加の利益のことです。"],["block-confirmations","ブロック承認数（コンファメーション）","ブロック承認数とは、取引が含まれたブロックの後にいくつのブロックが積み重なったかを示す数で、多いほど取引が覆される可能性が低くなります。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"「送金完了」と出ているのに届かない。どこを調べるべき？"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"ja","term":"KYC不要の取引所（ノーKYC取引所）","aka":["本人確認不要の取引所","ノーKYC取引所","no-KYC exchange"],"short":"KYC不要の取引所とは、身分証明書による本人確認なしで登録や取引、一定額までの出金ができる暗号資産取引所や交換サービスのことです。","body":[[["分散型取引所","dex"],"（DEX）は、",["ウォレット","crypto-wallet"],"を接続するだけで使えるため、そもそも",["本人確認","kyc"],"の仕組みがありません。一方、中央集権型の取引所でも、一定額までは本人確認なしで出金できる仕組みを用意しているところがあります。ただし、規制の強化によりその範囲は年々狭まっています。"],"KYC不要の取引所を使うと、個人情報を渡さずに済む一方、トラブル時に取引所や当局の保護を受けにくくなります。また、後から突然KYCを求められて、完了するまで出金できなくなるケースもあります。","日本の居住者の場合、国内で登録されていない海外の事業者が日本居住者を勧誘することは問題視されており、金融庁が警告を出した事業者もあります。使う前に、自分の住む国からの利用が規約で認められているかを確認することが大切です。"],"example":"ある取引所が、KYCなしでも1日あたり1 BTC相当まで出金できるとしていたとします。あなたが本人確認なしで5,000 USDTを入金し、取引で7,000 USDTに増やしたとしましょう。その後、規約の変更でKYCが必須になり、未完了のアカウントは出金できなくなりました。この場合、7,000 USDTを引き出すには結局KYCを完了する必要があり、居住国が対象外の国だと判明すれば、口座が制限される可能性もあります。本人確認なしの気軽さには、こうした後からのリスクがあることを覚えておきましょう。","mistakes":["KYC不要の状態がずっと続くと考え、大きな金額を預けたままにしてしまう。","規約で利用が禁止されている国から、VPNを使ってアクセスする。","本人確認がない手軽さを理由に、運営実態のわからない新しい取引所を選んでしまう。"],"faq":[{"q":"KYC不要の取引所は違法ですか？","a":"国や事業者の登録状況によって扱いが異なります。自分の国で登録されていない事業者を使うと、トラブル時に保護を受けられない点に注意が必要です。"},{"q":"DEXは本人確認なしで使えますか？","a":"多くのDEXはウォレットを接続するだけで使えます。ただし、フロントエンドのサイトが地域によってアクセスを制限している場合もあります。"}],"title":"KYC不要の取引所とは？本人確認なしのリスク","description":"KYC不要（本人確認不要）の取引所の意味、DEXとの違い、出金制限や規約変更などのリスク、使う前に確認すべき点を解説します。","related":[["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["withdrawal-fee","出金手数料","出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC（本人確認）の仕組みと、身分証は誰に提出すべきか？"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"ja","term":"法定通貨オンランプ（入金ルート）","aka":["オンランプ","法定通貨入金","fiat on-ramp"],"short":"法定通貨オンランプとは、円やドルなどの法定通貨を暗号資産に交換するための入口となるサービスや手段のことで、銀行振込、クレジットカード、P2P取引などがあります。","body":[[["暗号資産","cryptocurrency"],"を始めるには、まず法定通貨を暗号資産に換える必要があります。代表的な方法は、国内取引所への銀行振込、クレジットカードやデビットカードでの購入、海外取引所の",["P2P取引","p2p-trading"],"、外部の決済業者を通じた購入などです。反対に、暗号資産を法定通貨に戻す出口は「オフランプ」と呼ばれます。"],["方法によって、手数料、反映までの時間、",["本人確認","kyc"],"の要件が大きく異なります。銀行振込は手数料が比較的安いことが多い一方、カード購入はすぐに買える代わりに手数料が高くなりがちです。表示された手数料だけでなく、為替レートや",["スプレッド","bid-ask-spread"],"に含まれる実質的なコストも確認しましょう。"],"どの方法も、利用する国や取引所によって対応状況が異なります。日本の居住者であれば、金融庁に登録された国内取引所に円で入金し、そこで購入してから必要に応じて送金するのが一般的なルートです。"],"example":["あなたが100,000円分のUSDTを手に入れたいとします。方法Aはカード購入で、手数料が4%、レートは1 ",["USDT","usdt"],"＝150円です。手数料4,000円を引いた96,000円分なので、受け取れるのは640 USDTです。方法Bは国内取引所への銀行振込で、振込手数料が200円、スプレッドを含めた実質レートが1 USDT＝151円だとします。99,800円÷151で約660 USDTを受け取れます。差は約20 USDTで、金額が大きくなるほどこの差は広がります。数字は説明用の例で、実際の条件は各サービスで確認してください。"],"mistakes":["表示された手数料だけを比べ、為替レートやスプレッドに含まれるコストを見落とす。","初めての入金で大きな金額を一度に送り、反映されないときに慌てる。","SNSで紹介された個人間の振込を、取引所のP2P取引と同じように安全だと考える。"],"faq":[{"q":"暗号資産を買うのに一番安い方法は何ですか？","a":"一般的には銀行振込で取引所に入金し、取引所の板で購入する方法がコストを抑えやすいです。ただし条件はサービスごとに違うため、手数料とレートの両方を比べる必要があります。"},{"q":"オンランプとオフランプの違いは何ですか？","a":"オンランプは法定通貨から暗号資産に換える入口、オフランプは暗号資産を法定通貨に戻す出口です。どちらも手数料と本人確認の条件を確認しておくことが大切です。"}],"title":"法定通貨オンランプとは？暗号資産の入金ルート","description":"法定通貨オンランプの意味、銀行振込・カード・P2Pなど入金方法の違い、手数料とレートを含めた実質コストの比べ方を解説します。","related":[["p2p-trading","P2P取引（個人間取引）","P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"最初の入金：資金はどこから来て、どこへ入るのか？"},"coin":null,"tool":null,"cta":true}});
